import java.util.*;
public class TakeMetro {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int M = scanner.nextInt();
        //saves mod annoyances
        int S = scanner.nextInt()-1;
        long T = scanner.nextLong();
        while (T%N!=0) {
            if (S < M) {
                S = (int)((S + T) % N);
            } else {
                S = (int)((((S - T) % N) + N ) % N);
            }
            T--;
        }
        T /= N;
        //periodically shows up at same station, though not sure where yet
        int[] last = new int[N];
        Arrays.fill(last, -1);
        int cur = 0;
        //saw ourselves at the 0th round of N train takes
        last[S] = cur;
        while(T-- > 0) {
            for(int i = N-1; i > 0; i--) {
                if (S < M) {
                    S = (S + i) % N;
                } else {
                    S = (((S - i) % N) + N) % N;
                }
            }
            cur++;
            if (last[S] != -1) {
                T = T%(cur-last[S]);
                last[S] = cur;
            }
            else {
                last[S] = cur;
            }
        }
        System.out.println((S+1));
    }
}

